const rawItems = $input.all().map((item) => item.json);
const now = Date.now();
const developerTerms = ['developer', 'coding', 'code', 'agent', 'agentic', 'mcp', 'model context protocol', 'ide', 'cli', 'sdk', 'api', 'automation', 'workflow', 'testing', 'evaluation', 'observability', 'open source', 'framework', 'debug', 'deploy', 'database', 'security', 'performance'];
const harnessTerms = ['agent harness', 'orchestration', 'tool calling', 'computer use', 'memory', 'evals', 'sandbox', 'guardrail', 'tracing', 'prompt management'];
const categoryRules = [
  ['security', ['security', 'vulnerability', 'cve', 'supply chain', 'malware', 'patch']],
  ['databases', ['database', 'postgres', 'mysql', 'sqlite', 'query engine', 'storage']],
  ['testing', ['testing', 'unit test', 'evaluation', 'evals', 'benchmark']],
  ['observability', ['observability', 'tracing', 'telemetry', 'monitoring']],
  ['deployment', ['deploy', 'deployment', 'container', 'serverless', 'cloud']],
  ['languages', ['programming language', 'compiler', 'runtime', 'typescript', 'javascript', 'python', 'rust']],
  ['performance', ['performance', 'latency', 'faster', 'optimization', 'build time']],
  ['agents', ['agent', 'agentic', 'mcp', 'tool calling', 'computer use', 'harness']],
  ['automation', ['automation', 'workflow', 'cli']],
  ['frameworks', ['framework', 'sdk', 'api', 'open source']],
];
const authorityWeights = { 'openai.com': 18, 'github.blog': 18, 'huggingface.co': 17, 'blog.google': 17, 'aws.amazon.com': 16, 'vercel.com': 15, 'blog.jetbrains.com': 15, 'producthunt.com': 10, 'dev.to': 8 };
const normalized = [];
const seen = new Set();
for (const item of rawItems) {
  const sourceUrl = String(item.link ?? item.guid ?? '').trim();
  if (!sourceUrl || seen.has(sourceUrl)) continue;
  seen.add(sourceUrl);
  const publisher = (sourceUrl.split('://')[1] ?? '').split('/')[0].split('?')[0].split('#')[0].replace(/^www\./, '').toLowerCase() || 'unknown';
  const title = String(item.title ?? '').trim();
  const summary = String(item.contentSnippet ?? item.content ?? item.description ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 900);
  const engagementPoints = Number(summary.match(/points:\s*(\d+)/i)?.[1] ?? NaN);
  const engagementComments = Number(summary.match(/comments:\s*(\d+)/i)?.[1] ?? NaN);
  const searchable = `${title} ${summary}`.toLowerCase();
  const publishedAt = item.isoDate ?? item.pubDate ?? item.updated ?? '';
  const publishedMs = Date.parse(publishedAt);
  const ageDays = Number.isFinite(publishedMs) ? Math.max(0, (now - publishedMs) / 86400000) : 365;
  const recencyScore = ageDays <= 2 ? 30 : ageDays <= 7 ? 24 : ageDays <= 14 ? 17 : ageDays <= 30 ? 10 : 3;
  const developerHits = developerTerms.filter((term) => searchable.includes(term));
  const harnessHits = harnessTerms.filter((term) => searchable.includes(term));
  const developerRelevance = Math.min(30, developerHits.length * 5 + Math.min(4, harnessHits.length));
  const authorityScore = Object.entries(authorityWeights).find(([domain]) => publisher.includes(domain))?.[1] ?? 6;
  const toolTokens = [...new Set(title.toLowerCase().match(/[a-z][a-z0-9+.-]{2,}/g) ?? [])].filter((token) => !developerTerms.includes(token) && !['with', 'from', 'your', 'this', 'that', 'the', 'and', 'for', 'new'].includes(token));
  const contentCategory = categoryRules.find(([, terms]) => terms.some((term) => searchable.includes(term)))?.[0] ?? 'general-engineering';
  normalized.push({ title, summary, source_url: sourceUrl, publisher, content_category: contentCategory, published_at: publishedAt, age_days: Math.round(ageDays * 10) / 10, recency_score: recencyScore, developer_relevance: developerRelevance, authority_score: authorityScore, matched_developer_terms: developerHits, matched_harness_terms: harnessHits, tool_tokens: toolTokens.slice(0, 8), engagement_points: Number.isFinite(engagementPoints) ? engagementPoints : null, engagement_comments: Number.isFinite(engagementComments) ? engagementComments : null });
}
const tokenSources = new Map();
for (const item of normalized) for (const token of item.tool_tokens) {
  if (!tokenSources.has(token)) tokenSources.set(token, new Set());
  tokenSources.get(token).add(item.publisher);
}
for (const item of normalized) {
  const crossSourceMentions = Math.max(1, ...item.tool_tokens.map((token) => tokenSources.get(token)?.size ?? 1));
  const momentumScore = Math.min(22, (crossSourceMentions - 1) * 7 + Math.min(8, item.tool_tokens.length));
  const engagementScore = item.engagement_points != null ? Math.min(20, Math.round(Math.log2(item.engagement_points + (item.engagement_comments ?? 0) + 1) * 2.5)) : 0;
  item.cross_source_mentions = crossSourceMentions;
  item.momentum_score = momentumScore;
  item.engagement_score = engagementScore;
  item.trend_score = Math.min(120, item.recency_score + item.developer_relevance + item.authority_score + momentumScore + engagementScore);
  item.seo_terms = [...new Set([...item.matched_developer_terms, ...item.matched_harness_terms, ...item.tool_tokens.slice(0, 4)])].slice(0, 10);
}
const ranked = normalized.filter((item) => item.developer_relevance >= 5).sort((a, b) => b.trend_score - a.trend_score).slice(0, 60);
if (ranked.length < 5) throw new Error('INSUFFICIENT_DEVELOPER_TOOL_SIGNALS');
return ranked.map((json) => ({ json }));

// Bounds the outer research-restart loop. Without this, an execution where Claude keeps
// re-suggesting already-rejected topics (or the judge keeps rejecting everything) would call
// the research and judgement APIs forever instead of failing loudly and cheaply.
const staticData = $getWorkflowStaticData('node');
const executionId = String($execution.id);
if (staticData.executionId !== executionId) {
  staticData.executionId = executionId;
  staticData.researchCycles = 0;
}
staticData.researchCycles = (staticData.researchCycles || 0) + 1;
if (staticData.researchCycles > 4) {
  throw new Error(`JUDGEMENT_EXHAUSTED_ALL_RESEARCH_CYCLES:${staticData.researchCycles}`);
}
return [{json: {...$json, research_cycle: staticData.researchCycles}}];

const rankedItems = $items('Score Developer Tool Trends').map((item) => item.json).filter((item) => item.source_url);
const topicArchive = ($json?.recent || []).map((t) => `${t.tool_name}: ${t.topic} (${t.category})`);
const publisherCounts = new Map();
const categoryBuckets = new Map();
for (const item of rankedItems.sort((a, b) => b.trend_score - a.trend_score)) {
  const count = publisherCounts.get(item.publisher) ?? 0;
  if (count >= 6) continue;
  publisherCounts.set(item.publisher, count + 1);
  const category = item.content_category || 'other';
  if (!categoryBuckets.has(category)) categoryBuckets.set(category, []);
  categoryBuckets.get(category).push(item);
}
const sourceItems = [];
const categories = [...categoryBuckets.keys()];
while (sourceItems.length < 45 && categories.some((category) => categoryBuckets.get(category).length)) {
  for (const category of categories) {
    const next = categoryBuckets.get(category).shift();
    if (next) sourceItems.push(next);
    if (sourceItems.length >= 45) break;
  }
}
if (sourceItems.length < 5) throw new Error('RESEARCH_INSUFFICIENT_TIP_SIGNALS');
const topicShape = {topic:'',tool_name:'',category:'',one_line_value:'',what_it_is:'',why_not_obvious:'',concrete_payoff:'',who_it_helps:'',hook:'',visual_angle:'',trend_score:0,claims:[{claim_id:'c1',statement:'',source_url:'',publisher:'',published_at:'',retrieved_at:new Date().toISOString(),confidence:0,verification_notes:''}],seo_brief:{primary_keyword:'',related_keywords:[''],search_intent:'informational|tutorial',title_options:['','',''],description:'',hashtags:['']}};
const schema = {recommended_topic:topicShape,candidates:[topicShape],research_policy:{requires_human_review:true,content_disclosure:'AI-assisted research and narration; edited visuals.'}};
const prompt = `You are an evidence-first researcher for __TOPIC_NAME__, an ultra-short (10-15 second) vertical video series that teaches working developers one tip or trick they are probably NOT aware of. Analyze only the RANKED SOURCE MATERIAL below. Never invent commands, flags, shortcuts, behavior, or claims that are not directly supported by the material.

This show covers ONLY __TOPIC_SCOPE__. Reject every candidate outside that scope, even a strong one -- a sibling show already covers other developer topics, and diluting this pool is exactly the mistake this show exists to avoid. If fewer than 5 source items are genuinely in scope, return fewer candidates rather than stretching the definition.

Find genuinely non-obvious tips and tricks within that scope: features almost nobody enables, commands that replace a clumsy multi-step habit, flags that fix a common annoyance, lesser-known behavior, debugging techniques, or a small workflow change with an outsized payoff.

The hard constraint is TIME: the finished video is only 10-15 seconds, spoken as a four-line back-and-forth. A candidate only qualifies if its entire value fits in one sentence of setup and one sentence of payoff -- reject anything that needs paragraphs of context, multiple steps, or "it depends" caveats to land. Reject generic advice everyone already knows (e.g. "use version control", "write tests"), vague productivity platitudes, and anything that isn't a specific, nameable, triable action.

For each candidate, fill in why_not_obvious: the specific reason most developers have never seen or used this (buried in docs, replaced an old muscle-memory habit, requires an option most people never open, etc.) -- this field is what a later judgement step uses to decide whether the tip is genuinely worth 10-15 seconds of someone's attention. Also fill concrete_payoff: the exact time saved, bug class avoided, or friction removed, stated as a specific outcome, not a vague benefit.

For the hook field: write it as a genuine, surprising claim about the tip, stated in 14 words or fewer, that could open the video and make a developer stop scrolling in the first 3-4 seconds. Use a contrarian claim, a mistake most people make, or a concrete before/after gap. Sharpen the framing, never the facts -- the hook must still be fully supported by the claims.

${topicArchive.length ? `PERMANENT EXCLUSION ARCHIVE -- tips already covered or already rejected as not worth a video: ${topicArchive.join('; ')}. Never choose any archived tip or a substantially equivalent one, even phrased differently.` : ''}

Choose exactly 5 distinct candidates from different categories when the evidence allows, ranked best-first. recommended_topic must equal candidates[0]. Every candidate must include the full evidence and SEO fields shown in the schema, including at least one exact source-backed claim, so any unused candidate can safely replace the first choice. Every factual claim must cite an exact source_url from the material.

Create an SEO brief around natural developer search language. Titles should promise a concrete, specific benefit -- prefer a number, a contrast, or a named limitation over generic phrasing. Limit hashtags to 5-8.

Return ONLY valid JSON matching this schema:
${JSON.stringify(schema)}

RANKED SOURCE MATERIAL:
${JSON.stringify(sourceItems)}`;
return [{json:{prompt,source_count:sourceItems.length,sources:sourceItems,scoring_version:'developer-tips-v1'}}];

const originalPrompt = $items('Build Tips Research Prompt')[0]?.json?.prompt ?? '';
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
const errorType = String(body?.error?.type ?? body?.type ?? '').trim();
if (statusCode >= 200 && statusCode < 300 && text) {
  return [{ json: { use_qwen_fallback: false, response: text, research_provider: 'anthropic', research_model: body?.model ?? 'claude', prompt: originalPrompt } }];
}
const fallbackReason = statusCode < 200 || statusCode >= 300 ? `${statusCode}_${errorType || 'http_error'}` : 'empty_response';
return [{ json: { use_qwen_fallback: true, prompt: originalPrompt, research_provider: 'qwen-fallback', fallback_reason: fallbackReason } }];

const payload = $json;
let raw = '';
if (typeof payload === 'string') raw = payload;
else if (typeof payload.body === 'string') raw = payload.body;
else if (typeof payload.data === 'string') raw = payload.data;
else if (typeof payload.response === 'string') raw = payload.response;
else raw = JSON.stringify(payload);
if (!raw) throw new Error('RESEARCH_EMPTY_RESPONSE');
let generated = raw;
try { generated = JSON.parse(raw).response ?? raw; } catch {
  const lines = raw.split(/\r?\n/).filter(Boolean);
  const chunks = [];
  let isNdjson = lines.length > 1;
  for (const line of lines) {
    try { chunks.push(JSON.parse(line)); } catch { isNdjson = false; break; }
  }
  if (isNdjson && chunks.every((chunk) => typeof chunk.response === 'string')) generated = chunks.map((chunk) => chunk.response).join('');
}
const fenced = generated.match(/```(?:json)?\s*([\s\S]*?)```/i);
const candidate = String(fenced?.[1] ?? generated).trim();
let research;
const end = candidate.lastIndexOf('}');
for (const start of [0, ...[...candidate.matchAll(/\{/g)].map((match) => match.index)]) {
  if (end < start) continue;
  try {
    const parsed = JSON.parse(candidate.slice(start, end + 1));
    if (parsed?.recommended_topic?.claims?.length) { research = parsed; break; }
  } catch {}
}
if (!research) throw new Error('RESEARCH_INVALID_JSON: no valid JSON object with recommended_topic.claims found');
const provider = payload.research_provider ?? 'qwen-fallback';
const model = payload.research_model ?? 'tushin-agent:latest';
return [{ json: { research, researched_at: new Date().toISOString(), research_provider: provider, model, requires_human_review: true } }];

const research = $json.research;
const recommended = research?.recommended_topic;
if (!recommended) throw new Error('JUDGEMENT_QUEUE_MISSING_RECOMMENDED_TOPIC');
const sameCandidate = (a, b) => String(a?.tool_name ?? '').trim() === String(b?.tool_name ?? '').trim()
  && String(a?.topic ?? '').trim() === String(b?.topic ?? '').trim();
const rest = (Array.isArray(research.candidates) ? research.candidates : []).filter((candidate) => !sameCandidate(candidate, recommended));
// recommended is already verified unused against topic history by "Select Unused Topic"; the
// remaining candidates keep their original researcher ranking as the fallback order.
const queue = [recommended, ...rest];
return [{json: {...$json, research, judgement_queue: queue, judgement_index: 0}}];

const queue = Array.isArray($json.judgement_queue) ? $json.judgement_queue : [];
const index = Number($json.judgement_index ?? 0);
const candidate = queue[index];
if (!candidate) throw new Error(`JUDGEMENT_QUEUE_EMPTY:${index}_OF_${queue.length}`);
const schema = {worth_it: true, confidence: 0.0, reason: '', failure_mode: 'headline_is_the_whole_tip|too_obvious_already_known|not_actually_non_obvious|no_concrete_payoff|needs_too_much_setup|null'};
const prompt = `You are the pre-production judge for a 10-15 second developer-tips video series. Your ONLY job: decide whether a developer who has ALREADY read the full idea below -- the hook, what it is, why it's non-obvious, and the payoff, exactly as a caption or thumbnail would reveal it before they tap play -- would still choose to watch the 10-15 second video instead of scrolling past.

This is a harsh bar. Most "tips" fail it because the caption already told the viewer everything of value: knowing the headline IS knowing the tip, so the video adds nothing. A tip clears the bar only when watching still buys the viewer something the headline alone can't: seeing exactly where the option lives, seeing the before/after, hearing the one nuance that prevents misuse, or confirming this isn't something they already do. Judge specifically from the perspective of an experienced developer who has seen a thousand "did you know" posts and skips almost all of them.

Score worth_it as true only if a developer would keep watching after already knowing the full idea. Set failure_mode to the single best reason when worth_it is false, or null when true.

IDEA UNDER REVIEW:
${JSON.stringify({tool_name: candidate.tool_name, topic: candidate.topic, category: candidate.category, hook: candidate.hook, what_it_is: candidate.what_it_is, why_not_obvious: candidate.why_not_obvious, concrete_payoff: candidate.concrete_payoff, who_it_helps: candidate.who_it_helps})}

Return ONLY valid JSON matching this schema:
${JSON.stringify(schema)}`;
return [{json: {...$json, candidate, prompt}}];

const state = $('Build Judgement Prompt').item.json;
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const text = Array.isArray(body?.content) ? body.content.filter((block) => block?.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim() : '';
