  }
  if (isNdjson && chunks.every((chunk) => typeof chunk.response === 'string')) generated = chunks.map((chunk) => chunk.response).join('');
}
const fenced = String(generated ?? '').match(/```(?:json)?\s*([\s\S]*?)```/i);
const candidateText = String(fenced?.[1] ?? generated ?? '').trim();
let verdict = null;
