return [{json: {worth_it: worthIt, reason, failure_mode: failureMode, research: updatedResearch, candidate, judgement_queue: state.judgement_queue, judgement_index: state.judgement_index}}];

const state = $('Normalize Judgement Verdict').item.json;
const queue = Array.isArray(state.judgement_queue) ? state.judgement_queue : [];
